const fs = require('fs');
const zlib = require('zlib');
const PDFDocument = require('pdfkit');

// --- Extract Maya Chen's section from the docx ---
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');
let offset = 0;
let lines = [];

while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig !== 0x04034b50) break;
  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const nameLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const name = buf.toString('utf-8', offset + 30, offset + 30 + nameLen);
  const dataStart = offset + 30 + nameLen + extraLen;

  if (name === 'word/document.xml') {
    let data;
    if (compMethod === 0) data = buf.slice(dataStart, dataStart + compSize);
    else data = zlib.inflateRawSync(buf.slice(dataStart, dataStart + compSize));
    const xml = data.toString('utf-8');

    const paragraphs = [];
    const pRegex = /<w:p[ >][\s\S]*?<\/w:p>/g;
    let match;
    while ((match = pRegex.exec(xml)) !== null) {
      const pXml = match[0];
      const texts = pXml.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
      paragraphs.push(texts.map(t => t.replace(/<[^>]+>/g, '')).join(''));
    }

    let start = -1, end = paragraphs.length;
    for (let i = 0; i < paragraphs.length; i++) {
      if (paragraphs[i].includes('Maya Chen')) { start = i; }
      else if (start !== -1 && paragraphs[i].match(/Email:/) && !paragraphs[i].includes('maya.chen')) {
        for (let j = i - 1; j >= start; j--) {
          if (paragraphs[j].trim() && !paragraphs[j].includes('Order ORD') && !paragraphs[j].includes('Items:') && !paragraphs[j].includes('maya.chen')) { end = j; break; }
        }
        break;
      }
    }
    if (start !== -1) {
      for (let i = start; i < end; i++) {
        if (paragraphs[i].trim()) lines.push(paragraphs[i]);
      }
    }
    break;
  }
  offset = dataStart + compSize;
}

// --- Build the PDF ---
const doc = new PDFDocument({ margin: 50 });
const outPath = '/workspace/testbed/docs/Maya_Chen_Customer_Activity_Report.pdf';
const stream = fs.createWriteStream(outPath);
doc.pipe(stream);

// Title
doc.fontSize(18).font('Helvetica-Bold').text('Customer Activity Report', { align: 'center' });
doc.moveDown(1.2);

// Customer name
doc.fontSize(14).font('Helvetica-Bold').text(lines[0]); // Maya Chen
doc.moveDown(0.3);

// Email / Loyalty / Credit line
const info = lines[1]; // Email: ... | Loyalty Tier: ... | Store Credit: ...
const infoParts = info.split('|').map(s => s.trim());
doc.fontSize(10).font('Helvetica');
infoParts.forEach(part => {
  const [label, value] = part.split(':').map(s => s.trim());
  doc.font('Helvetica-Bold').text(label + ': ', { continued: true }).font('Helvetica').text(value);
});

doc.moveDown(0.8);

// Divider
doc.moveTo(50, doc.y).lineTo(doc.page.width - 50, doc.y).strokeColor('#cccccc').stroke();
doc.moveDown(0.6);

// Orders
doc.fontSize(12).font('Helvetica-Bold').text('Orders');
doc.moveDown(0.5);

for (let i = 2; i < lines.length; i++) {
  const line = lines[i];
  if (line.startsWith('Order ORD')) {
    // Parse: Order ORD-XXXX — DATE | Status: xxx | Total: $xx
    const parts = line.split('|').map(s => s.trim());
    const orderAndDate = parts[0]; // Order ORD-xxx — date
    const status = parts[1];       // Status: xxx
    const total = parts[2];        // Total: $xx

    const [orderPart, datePart] = orderAndDate.split('—').map(s => s.trim());
    const orderId = orderPart.replace('Order ', '');
    const statusVal = status.split(':')[1].trim();
    const totalVal = total.split(':')[1].trim();

    doc.moveDown(0.3);
    doc.fontSize(10).font('Helvetica-Bold').text(orderId, { continued: true });
    doc.font('Helvetica').text('    Date: ' + datePart, { continued: true });
    doc.text('    Total: ' + totalVal);

    // Status with color
    const statusColor = statusVal === 'confirmed' ? '#2e7d32' : '#c62828';
    doc.font('Helvetica').text('Status: ', { continued: true });
    doc.fillColor(statusColor).text(statusVal).fillColor('#000000');

  } else if (line.trimStart().startsWith('Items:')) {
    const items = line.replace(/^\s*Items:\s*/, '').split(',').map(s => s.trim());
    doc.fontSize(9).font('Helvetica').text('Items:');
    items.forEach(item => {
      doc.text('  • ' + item);
    });
  }
}

// Footer
doc.moveDown(1.5);
doc.moveTo(50, doc.y).lineTo(doc.page.width - 50, doc.y).strokeColor('#cccccc').stroke();
doc.moveDown(0.4);
doc.fontSize(8).font('Helvetica-Oblique').fillColor('#888888')
  .text('Generated from customer_report.docx', { align: 'center' });

doc.end();
stream.on('finish', () => console.log('PDF saved to: ' + outPath));
"
